        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：忽略探測船本身以 14 m/s 前進，誤套靜止回聲公式 346 × 4.0 ÷ 2 ＝ 692 m。\n• 選項 (B) 錯誤：664 m 是「4 秒後聽到回聲當下」船與山壁的剩餘距離（720 − 56 ＝ 664 m，或誤套駛離公式 (346−14)×4÷2），並非題目所問的「鳴笛瞬間」距離；且海底深度忘記除以 2 誤算為 1,800 m。\n• 選項 (D) 錯誤：山壁距離算對 720 m，但海底聲納忘了來回兩趟須除以 2，誤把總路徑 1,800 m 當成水深。",
