      "stem": "小軒在暗室進行針孔成像實驗，在針孔紙盒前方距離針孔 30 cm 處放置一個發光的「F」字形 LED 燈（從小軒站在燈後面向針孔與紙屏觀察，燈體長豎筆畫在左側、兩條橫槓在右上方），而紙盒內部針孔到半透明描圖紙屏的距離（盒長）固定為 15 cm。關於小軒在紙屏上觀察到的影像特徵及後續實驗變化的敘述，下列何者正確？",
