        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據歐姆定律與串並聯等效電阻法則（Kc-IV-7）：\n1. 並聯等效電阻 R_並：1/R_並 ＝ 1/R_乙 ＋ 1/R_丙；且並聯兩支路端電壓相等（V_乙 ＝ V_丙），故 I_乙 × R_乙 ＝ I_丙 × R_丙（並聯電流比與電阻成「反比」！）。\n2. 串聯總等效電阻 R_總 ＝ R_甲 ＋ R_並，總電流 I_總 ＝ V_總 ÷ R_總。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 求乙（3 Ω）與丙（6 Ω）的並聯等效電阻 R_並：\n   1/R_並 ＝ 1/3 ＋ 1/6 ＝ 2/6 ＋ 1/6 ＝ 3/6 ＝ 1/2 ⇒ R_並 ＝ 2 Ω。\n2. 求全電路總等效電阻 R_總與總電流 I_總：\n   R_總 ＝ R_甲 ＋ R_並 ＝ 2 Ω ＋ 2 Ω ＝ 4 Ω。\n   I_總 ＝ V_總 ÷ R_總 ＝ 12 V ÷ 4 Ω ＝ 3 A。\n3. 求乙、丙分流比（並聯等電壓，電流與電阻成反比）：\n   I_乙：I_丙 ＝ (1/3)：(1/6) ＝ 2：1（實際數值：3 A 分成 I_乙 ＝ 2 A、I_丙 ＝ 1 A；驗算並聯端電壓：2A×3Ω ＝ 6 V、1A×6Ω ＝ 6 V，加上甲壓降 3A×2Ω ＝ 6 V，6V＋6V ＝ 12V 完美閉環！），故選 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：算對總電流 3 A，但分流時誤以為電阻越大電流越大，把電流比寫成正比 3：6 ＝ 1：2（水阻越大的水管水流反而越小！）。\n• 選項 (C) 錯誤：把乙、丙並聯誤當成全部串聯（2＋3＋6＝11 Ω，12/11≈1.09 A 且等電流 1：1）。\n• 選項 (D) 錯誤：算並聯電阻時倒數忘記翻回來，或漏加主幹線 2 Ω。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】記熟兩組黃金秒算數字：「3 Ω 並聯 6 Ω 等於 2 Ω」、「4 Ω 並聯 4 Ω 等於 2 Ω」、「6 Ω 並聯 12 Ω 等於 4 Ω」；算完立刻用「各段電壓相加 ＝ 電池總電壓」驗算，保證零失分！"
