        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱週期表規律（Aa-IV-1、Aa-IV-4）：\n1. 現代週期表由莫色勒確立依「原子序（質子數）」由小到大排列；橫列稱為「週期」，直行稱為「族」，同一「族（直行）」元素因價電子組態相似而具有相似化學性質。\n2. 第 1 族鹼金屬（Li、Na、K）：密度小於水、質軟有銀白光澤，遇水劇烈反應放出可燃氫氣（2Na ＋ 2H₂O → 2NaOH ＋ H₂↑）並使水溶液呈強鹼性（酚酞變紅），但密度大於礦物油（約 0.8 g/cm³）且不與其反應，故儲於礦物油（石油）中。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢驗甲族（鹼金屬）：Li、Na、K 活性極大（活性 K ＞ Na ＞ Li），暴露空氣瞬間氧化失去光澤，遇水劇烈放熱產氫，實驗室必須浸泡於礦物油中隔絕空氣與水氣。\n2. 檢驗乙族（鹼土金屬）：Mg、Ca、Ba 化合物廣泛存在地殼中，其氯化水溶液加入碳酸鈉（Na₂CO₃）或稀硫酸時，易生成碳酸鹽（MgCO₃、CaCO₃、BaCO₃）或硫酸鋇／鈣等白色沉澱，完全吻合選項 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：兩處顛倒！依「原子量」排列是十九世紀門得列夫的舊週期表，現代週期表是依「原子序（質子數）」排列；且化學性質相似的是同一「直行（族）」，而非橫列（週期）！\n• 選項 (B) 錯誤：三處實驗現象全錯！鈉（密度約 0.97 g/cm³）與鉀（約 0.86 g/cm³）密度皆比水小，投入水中會「浮在水面」迅速滑動劇烈反應（鉀甚至會起火燃燒冒紫紅色火光），且生成強鹼 NaOH／KOH 會使酚酞由無色變為「粉紅色／紅色」！\n• 選項 (D) 錯誤：鈍氣（He、Ne、Ar）原子極為安定，常溫下全部以「單原子分子（He、Ne、Ar）」存在而非雙原子！且焊接金屬最常用的保護氣是空氣中含量最多的鈍氣「氬氣（Ar）」（氦氣 He 用於填充安全氣球與飛船，氖氣 Ne 裝入霓虹燈管通電發紅光）。",
