      "title": "【110 會考自然質量守恆實驗改編】寶特瓶大理石加鹽酸密閉與開蓋排氣三階段秤重",
      "stem": "阿翰進行質量守恆定律驗證實驗：他在一個耐壓塑膠寶特瓶底部放入 10 g 大理石碎塊（主要成分為 CaCO₃），並將裝有 15 mL 稀鹽酸的小試管直立放入瓶內（兩者尚未接觸），旋緊瓶蓋密封後置於電子天平上秤得總質量為 M₁；接著將寶特瓶傾斜使稀鹽酸流出與大理石混合，觀察到瓶內產生大量無色氣泡且瓶身微微變硬鼓脹，待氣泡完全停止後（瓶蓋仍旋緊）秤得總質量為 M₂；最後將瓶蓋緩緩旋開，聽到「嘶嘶」排氣聲，待氣體排盡後將瓶蓋一併放回天平盤上秤得總質量為 M₃（忽略瓶身極微小浮力變化）。關於 M₁、M₂、M₃ 的大小關係與原理解釋，下列何者正確？",
