      "steps": [
        "【第 1 步：審題定位 · 題眼與已知】題幹給出「密閉容器」中甲、乙、丙、丁反應前後的克數表。注意反應後甲還剩 6 g、乙還剩 x g，代表反應物並未全部耗盡（或達特定反應終點），絕對不能拿表面讀數 30、40 直接當反應量！",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱質量守恆定量分析（Ja-IV-1、tr-IV-1）：\n1. 密閉系統總質量守恆：Σm_反應前 ＝ Σm_反應後，先解出未知數 x。\n2. 計算各物質質量變化量 Δm ＝ m_後 − m_前：Δm ＜ 0（質量減少）為「反應物」；Δm ＞ 0（質量增加）為「生成物」；Δm ＝ 0（質量不變）可能為催化劑，也可能只是完全不參與反應的旁觀雜質。\n3. 化學反應定量比例必須使用「實際消耗或生成的質量變化量｜Δm｜」計算！",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 求未知數 x：反應前總質量 ＝ 30 ＋ 40 ＋ 5 ＋ 0 ＝ 75 g；反應後總質量 ＝ 6 ＋ x ＋ 5 ＋ 44 ＝ 55 ＋ x。由 55 ＋ x ＝ 75，解得 x ＝ 20（g）。\n2. 逐一計算各物質變化量 Δm ＝ m_後 − m_前：\n   • 甲：6 − 30 ＝ −24 g（減少 24 g ➔ 反應物，實際消耗 24 g）。\n   • 乙：20 − 40 ＝ −20 g（減少 20 g ➔ 反應物，實際消耗 20 g，剩餘 20 g 未反應）。\n   • 丙：5 − 5 ＝ 0 g（質量不變 ➔ 未消耗，不寫入反應物與生成物主體）。\n   • 丁：44 − 0 ＝ ＋44 g（增加 44 g ➔ 唯一生成物，實際生成 44 g）。\n3. 驗證反應類型與質量比：消耗總重（24 ＋ 20 ＝ 44 g）恰好等於生成總重（44 g），反應類型為「甲 ＋ 乙 → 丁」的化合反應；實際參與反應的質量比 甲：乙：丁 ＝ 24：20：44 ＝（同除以 4）＝ 6：5：11，故選 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：段考最常見失分原因——直接拿「反應前投入量 30 g、40 g」去比生成量 44 g！忽略瓶內還有 6 g 的甲與 20 g 的乙根本沒參與反應。\n• 選項 (C) 錯誤：除了 x 算錯（應為 20 非 15）外，還掉入邏輯陷阱！丙在反應前後皆為 5 g，只代表丙沒有被消耗，它「可能是催化劑」，但也可能只是像惰性氣體氬氣或細沙一樣「完全無關的不反應雜質」，在沒有加做反應速率對照實驗前，不能斷言「必定是催化劑」！\n• 選項 (D) 錯誤：加減計算錯誤且顛倒因果，丁由 0 g 增加到 44 g 是「無中生有」的生成物，絕非反應物。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版在質量守恆進階題皆強調雙重驗算公式：「所有反應物減少克數總和 ｜ΣΔm_減｜ 必定精準等於 所有生成物增加克數總和 ΣΔm_增」！本題 24 ＋ 20 ＝ 44，一秒確認 x ＝ 20 與比例 6：5：11 無懈可擊！"
      ]
