        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱溶解度與重量百分濃度公式（Jb-IV-4）：\n1. 按水量比例換算最大可溶溶質克數：W_上限 ＝ 實際水重 × (S ÷ 100)。\n2. 重量百分濃度 P% ＝ [實際溶解溶質重 ÷ (實際溶解溶質重 ＋ 溶劑水重)] × 100%（切記：分母是「溶液總重」而非單獨水重，且杯底未溶解的固體沉澱絕對不可計入溶質或溶液總重！）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 計算 50 g 水在 25°C 的最大可溶食鹽量：W_上限 ＝ 50 × (36 ÷ 100) ＝ 18 g。\n2. 分析甲杯（50 g 水 ＋ 15 g 食鹽）：因為 15 g ＜ 18 g，食鹽全部溶解，杯底無沉澱（0 g），屬於「未飽和溶液」。\n   • 甲杯重量百分濃度 P_甲 ＝ [15 ÷ (50 ＋ 15)] × 100% ＝ (15 ÷ 65) × 100% ＝ (3 ÷ 13) × 100% ≈ 23.1%。\n3. 分析乙杯（50 g 水 ＋ 22 g 食鹽）：因為 22 g ＞ 18 g，最多僅能溶入 18 g 食鹽，杯底留下 22 − 18 ＝ 4 g 未溶食鹽沉澱，上層澄清液為「飽和溶液」。\n   • 乙杯重量百分濃度 P_乙 ＝ [18 ÷ (50 ＋ 18)] × 100% ＝ (18 ÷ 68) × 100% ＝ (9 ÷ 34) × 100% ≈ 26.5%。\n4. 綜合比較：甲未飽和無沉澱、乙飽和有 4 g 沉澱，且 P_甲（23.1%）＜ P_乙（26.5%），故正確選項為 (C)。",
