        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱溶解度與混合物分離原理（Jb-IV-4、Ab-IV-4）：\n1. 氣體溶解度鐵律：「溫度越低、壓力越大」，氣體對水的溶解度越大（反之高溫或減壓皆會使溶解氣體逸出）。\n2. 固體溶解度例外：大多數固體（如硝酸鉀）隨升溫溶解度增大，但「氫氧化鈣 Ca(OH)₂（熟石灰）」隨水溫升高溶解度反而減小！\n3. 粗鹽精製順序為「溶解 → 過濾（利用顆粒大小／溶解度差異） → 蒸發 → 結晶（利用沸點高低差異）」。",
