        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版皆補充一個極重要的實驗小細節：折疊濾紙時「外層撕去一小角」再沾水貼緊漏斗內壁，目的是避免空氣從雙層縫隙鑽入，維持漏斗頸內連續液柱重力牽引以加快過濾速率！"
