        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱常見強酸性質與實驗室安全規範（Jd-IV-2、tr-IV-1）：\n1. 濃硫酸「脫水性」：能強行將碳水化合物分子內部的氫原子與氧原子依 H：O ＝ 2：1 的水分子比例奪走，使有機物分解殘留黑色的碳（C），產生新物質，屬於「化學變化」。\n2. 濃硫酸稀釋鐵律：濃硫酸溶於水會放出極大量熱能！必須在「燒杯」中先裝水，再將密度大的濃硫酸沿玻璃棒緩慢倒入水中（酸入水）並不斷攪拌。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 解析實驗一（脫水碳化）：蔗糖 C₁₂H₂₂O₁₁ 為白色純物質化合物，遇濃硫酸發生化學脫水反應：C₁₂H₂₂O₁₁ →（濃 H₂SO₄ 奪去 11 H₂O）→ 12 C（黑色焦炭），證實濃硫酸具強烈脫水性且為化學變化。\n2. 解析實驗二（為何必須酸入水）：當將密度較大（1.84 g/cm³）的濃硫酸緩慢倒入密度較小（1.0 g/cm³）的水中時，濃硫酸會一邊下沉一邊分散，配合玻璃棒攪拌，放出的大量溶解熱能被整杯水均勻吸收，不會發生突沸噴濺，故正確選項為 (C)。",
