        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱氧化還原與活性判準（Jc-IV-1）：\n1. 置換鐵律：若單質 A ＋ 氧化物 BO → AO ＋ B 能發生反應（＋），代表「對氧活性：A ＞ B」，同時代表「氧化物安定性：AO ＞ BO」。\n2. 劑的角色反向記憶法：\n   • 還原劑 ＝ 搶走別人的氧、使別人還原（自己發生氧化反應）➔ 對氧活性越大的「單質」，還原力越強！\n   • 氧化劑 ＝ 供應氧給別人、使別人氧化（自己失去氧發生還原反應）➔ 對氧活性越小之元素所形成的「氧化物」，越不安定最易失氧，氧化力越強！",
