        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱摩擦力與力平衡原理（Eb-IV-4）：\n1. 當水平外力 F ＜ f_s,max 時，木塊保持靜止不動，合力必為 0，故實際靜摩擦力 f_s ＝ F（推多少就抵銷多少）。\n2. 當水平外力 F ＝ f_s,max 時，木塊處於恰將滑動的臨界瞬間，靜摩擦力達到極限值 f_s,max。\n3. 當水平外力 F ＞ f_s,max 時，木塊已開始滑動，改受定值「動摩擦力 f_k」（只要正向力與接觸面不變，動摩擦力不隨水平拉力增大而改變）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 甲測試（施力 F_甲 ＝ 500 gw）：因為 500 gw ＜ 最大靜摩擦力 800 gw，木塊推不動保持靜止，由水平合力為零可知實際靜摩擦力 f_甲 ＝ 500 gw（方向向左）。\n2. 乙測試（施力 F_乙 ＝ 800 gw）：恰等於最大靜摩擦力門檻，故臨界靜摩擦力 f_乙 ＝ 800 gw（方向向左）。\n3. 丙測試（施力 F_丙 ＝ 1200 gw）：因為 1200 gw ＞ 800 gw，木塊已克服最大靜摩擦力在桌面上向右滑動，此時所受摩擦力即為恆定的動摩擦力 f_丙 ＝ f_k ＝ 600 gw（多出的淨合力 1200 − 600 ＝ 600 gw 使木塊向右產生加速度），故依序為 500 gw、800 gw、600 gw，選 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：典型直覺迷思！看到甲測試「推不動」就以為桌面出了 800 gw 的最大靜摩擦力擋住它；試想若向右推 500 gw 而桌面卻向左推 800 gw，木塊豈不是會自己逆著手向左倒退飛出去？違反力平衡！\n• 選項 (B) 錯誤：誤以為丙測試滑動後仍然合力為零（f_丙 ＝ 1200 gw）；只有當題目特別聲明「施力 600 gw 使木塊等速度滑行」時拉力才等於動摩擦力，施力 1200 gw 時木塊做等加速度運動，動摩擦力仍維持 600 gw。\n• 選項 (C) 錯誤：混淆動摩擦力與最大靜摩擦力，忽略物體一旦滑動後摩擦力會微幅下降穩定在動摩擦力 600 gw。",
