        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱導體靜電感應與感應起電原理（Kc-IV-1）：\n1. 微觀鐵律：固體導體中原子核與帶正電的「質子」束縛於晶格位置絕不移動，唯有帶負電的「自由電子」可自由移動！\n2. 接地與斷開順序：地球是巨大電荷庫，手指觸碰金屬球時，在外加負電棒的持續排斥下，多餘自由電子經人體流向地面；隨後必須「先移開手指切斷接地通道」，最後「再移開塑膠棒」，使金屬球因總電子數少於總質子數而均勻帶正電。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 靠近感應階段：帶負電塑膠棒靠近左側，同性電相斥將金屬球內部分自由電子推向右側遠端；左側近端因缺乏電子顯現正電，右側遠端因聚集過多電子顯現負電。\n2. 觸碰接地階段：以手指觸碰金屬球接地（無論碰觸球面右側或任一點，導體與地球連成一體，右側變成非最遠端，地球才是真正的最遠端！），被塑膠棒排斥的自由電子經手指與人體流向地面。\n3. 斷開與撤離階段：先移開手指（鎖住缺電子狀態），再移開左側帶負電塑膠棒，正電荷（缺電子區）均勻分布於金屬球表面，最終金屬球帶「正電」，故選 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：犯了兩大致命錯誤！第一，「質子」深鎖原子核內絕不會移動；第二，若「先移開塑膠棒、再移開手指」，失去負電棒排斥後地面電子會立刻經手指流回金屬球中和，導致金屬球恢復不帶電！\n• 選項 (C) 錯誤：搞反接地電子流向！外加的是帶「負電」塑膠棒（排斥電子入地），只有當外加「正電」玻璃棒靠近時，才會吸引地面電子流入金屬球使其最終帶負電。\n• 選項 (D) 錯誤：混淆「暫時性靜電感應（未接地）」與「感應起電（有接地）」；若未接地直接移開塑膠棒，金屬球左右兩端正負電會立刻重新中和恢復電中性。",
