        "【第 2 步：破題關鍵 · 課綱概念與核心公式】結合電荷守恆定律與段考延伸庫侖定律：\n1. 兩完全相同金屬球接觸均分法則：異種電荷先中和抵銷，剩餘淨電量再平分，即接觸後每球帶電量 q₁' ＝ q₂' ＝ (q₁ ＋ q₂) ÷ 2（必須連同正負號進行代數相加！）。\n2. 庫侖靜電力平方反比公式：F ＝ k × |q₁ × q₂| ÷ d²，靜電力大小與兩電量絕對值乘積成正比，與兩球心距離的「平方」成反比。",
