        "操作一顏色變淺且分子總數增加；操作二壓縮瞬間顏色變深，隨後平衡向右移動直到顏色比壓縮前更淺",
        "操作一顏色變深且分子總數減少；操作二壓縮瞬間顏色不變，隨後平衡向左移動使顏色變深",
        "操作一顏色變淺且分子總數減少；操作二壓縮瞬間顏色變深，隨後平衡向右移動使顏色略變淺（但仍比壓縮前深）且分子總數減少"
