      "steps": [
        "【第 1 步：審題定位 · 題眼與已知】本題屬八下段考延伸之勒沙特列原理經典壓軸題。已知可逆反應式：2NO₂(紅棕色，係數 2) ⇌ N₂O₄(無色，係數 1) ＋ 熱（正反應為放熱反應，且向右反應時每 2 個分子合成 1 個分子，粒子總數減少）。操作一為「定容降溫」，操作二為「定溫體積減半壓縮」。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據動態平衡移動與段考延伸勒沙特列原理：① 溫度效應：降溫時系統往「放熱方向」移動以補充熱量；② 體積／壓力效應：壓縮氣體體積瞬間，所有氣體單位體積濃度同比例暴增（C ＝ n/V，V 減半則 [NO₂] 瞬間變 2 倍）；隨後因總壓增大，平衡往「氣體係數總和較小」方向移動以減緩壓力，但「抵銷作用永遠無法完全消除最初的外界改變」！",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 推導【操作一】（浸入冰水浴降溫）：正反應放熱（＋熱在右邊），降溫使平衡向右移動（2NO₂ → N₂O₄），紅棕色 NO₂ 消耗轉為無色 N₂O₄，故氣體紅棕色「變淺」；且每 2 個 NO₂ 變 1 個 N₂O₄，筒內氣體分子總數「減少」。\n2. 推導【操作二】（定溫體積壓縮為 1/2）：\n   • 壓縮瞬間：平衡尚未及移動，體積 V 減半使 [NO₂] 瞬間變為原來的 2 倍，故紅棕色「瞬間變深」！\n   • 邁向新平衡：總壓變大，平衡往氣體分子係數和較小的一方（左邊係數 2 → 右邊係數 1，即向右）移動，消耗部分 NO₂ 生成 N₂O₄，使筒內氣體分子總數「減少」，顏色由瞬間最深狀態「略微變淺」；但因體積只剩一半，新平衡的 [NO₂] 仍大於壓縮前原平衡濃度（介於 1 倍至 2 倍之間），故最終顏色仍比壓縮前深！\n3. 綜合核對，選項 (D) 每一環節皆精準無誤。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：將放熱反應降溫誤判為向左移動，且忽略體積壓縮瞬間單位體積粒子密度加倍必先變深。\n• 選項 (B) 錯誤：前半段分子數方向算反（2 變 1 應減少）；後半段掉入「過度抵銷陷阱」，誤以為向右移會使最終顏色比壓縮前更淺。\n• 選項 (C) 錯誤：誤以為壓縮瞬間顏色不變，且把加壓移動方向（應往係數小的一側）完全判反。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】南一與翰林補充講義在注射筒 NO₂ 實驗皆畫出 `[NO₂]-時間` 鋸齒圖：壓縮瞬間垂直跳升至 2C₀，再緩降收斂於約 1.6C₀（高於原水平線 C₀）。牢記「先垂直跳升、再微幅回落但不破原線」，任何段考壓軸圖形題都能一眼秒殺！"
      ]
