      "stem": "小安組裝一套導電性測試裝置（將兩根碳棒電極串聯直流電源與小燈泡），每次測試前皆以蒸餾水徹底洗淨並擦乾碳棒，依序針對室溫下六組樣品進行測試：【甲】純水（蒸餾水）、【乙】乾燥食鹽晶體（固態 NaCl）、【丙】食鹽水溶液、【丁】乙醇（酒精 C₂H₅OH）水溶液、【戊】葡萄糖（C₆H₁₂O₆）水溶液、【己】稀醋酸（CH₃COOH 水溶液）。關於這六組樣品的測試現象與電解質分類敘述，下列何者正確？",
