        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱電解質定義（Jb-IV-1）：① 凡「化合物」溶於水（或熔融態）能解離出自由移動的離子而導電者，即稱為電解質；② 離子化合物在「固態晶體」時正負離子被固定無法自由移動，故固態不導電，但該化合物本身仍歸類為電解質；③ 強電解質（如 NaCl）完全解離燈泡亮，弱電解質（如 CH₃COOH）部分解離燈泡暗，非電解質（如乙醇、葡萄糖）雖易溶於水但不解離，燈泡不亮。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 逐組判定燈泡亮暗：\n   • 甲（純水）：極難解離，離子濃度極微，一般小燈泡「不發亮」。\n   • 乙（乾燥食鹽晶體）：Na⁺ 與 Cl⁻ 束縛於晶格中無法自由移動，小燈泡「不發亮」（但 NaCl 溶於水可導電，故 NaCl 本身屬於電解質！）。\n   • 丙（食鹽水溶液）：NaCl 完全解離產生大量自由移動 Na⁺ 與 Cl⁻，屬強電解質，小燈泡「明亮」。\n   • 丁（乙醇水溶液）與戊（葡萄糖水溶液）：兩者皆極易溶於水，但以完整分子形態分散於水中不解離，小燈泡皆「不發亮」，乙醇與葡萄糖皆屬「非電解質」。\n   • 己（稀醋酸）：CH₃COOH 僅小部分解離為 H⁺ 與 CH₃COO⁻，屬弱電解質，小燈泡「微亮（較暗）」。\n2. 比對四個選項，僅選項 (C) 對發亮組別與物質分類之描述完全正確。",
