        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 設比例參數：依題意設溶液中 Na⁺ 有 2k 個、Mg²⁺ 有 3k 個、Cl⁻ 有 4k 個，並設未知的 SO₄²⁻ 有 xk 個（k ＞ 0）。\n2. 計算陽離子正電荷總電量：(2k) × 1 ＋ (3k) × 2 ＝ 2k ＋ 6k ＝ 8k（單位正電荷）。\n3. 計算陰離子負電荷總電量並套用電中性等式：(4k) × 1 ＋ (xk) × 2 ＝ 8k ➔ 4k ＋ 2xk ＝ 8k ➔ 2xk ＝ 4k ➔ 解得 x ＝ 2（即 SO₄²⁻ 有 2k 個）。\n4. 求題目指定的個數比：N(SO₄²⁻)：N(Cl⁻) ＝ 2k：4k ＝ 1：2，故正確答案為 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：完全忽略離子價數，誤用「陽離子個數和 ＝ 陰離子個數和」（2 ＋ 3 ＝ 4 ＋ x ➔ 誤得 x ＝ 1），算出 1：4，此為段考第一高頻失分陷阱！\n• 選項 (C) 錯誤：算對 SO₄²⁻ 需補足 4k 單位負電荷，卻忘記每個 SO₄²⁻ 帶 −2 價（漏除以 2 誤得 x ＝ 4），算出 4：4 ＝ 1：1。\n• 選項 (D) 錯誤：誤將陽離子總個數 2k ＋ 3k ＝ 5k 直接當成 SO₄²⁻ 個數，得出 5：4。",
