        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據酸鹼完全中和莫耳關係（Jd-IV-3）：恰好完全中和時，酸所解離出的 H⁺ 總莫耳數必等於鹼所解離出的 OH⁻ 總莫耳數，即 n(H⁺) ＝ n(OH⁻) ➔ a × M₁ × V₁ ＝ b × M₂ × V₂（其中 H₂SO₄ → 2H⁺ ＋ SO₄²⁻ 故 a ＝ 2；NaOH → Na⁺ ＋ OH⁻ 故 b ＝ 1）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 計算稀硫酸提供的 H⁺ 總莫耳數：V₁ ＝ 50 mL ＝ 0.050 L，故 n(H₂SO₄) ＝ 0.2 M × 0.050 L ＝ 0.010 mol；因 1 mol H₂SO₄ 解離出 2 mol H⁺，故 n(H⁺) ＝ 2 × 0.010 mol ＝ 0.020 mol。\n2. 列中和等式求 NaOH 體積 V₂：因 1 mol NaOH 解離出 1 mol OH⁻，需 n(OH⁻) ＝ 0.020 mol ＝ 0.5 M × V₂(L) ➔ V₂ ＝ 0.020 ÷ 0.5 ＝ 0.040 L ＝ 40 mL。\n3. 亦可用毫莫耳速算法：2 × 0.2 × 50 ＝ 1 × 0.5 × V₂ ➔ 20 ＝ 0.5 × V₂ ➔ V₂ ＝ 40 mL，故選 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：將二元酸的 2 倍乘錯邊（誤列成 0.2 × 50 ＝ 2 × 0.5 × V₂ ➔ V₂ ＝ 10 mL），把「1 個硫酸抵 2 個氫氧化鈉」寫反。\n• 選項 (B) 錯誤：完全忘記硫酸是二元酸，直接套用 M₁V₁ ＝ M₂V₂（0.2 × 50 ＝ 0.5 × V₂ ➔ V₂ ＝ 20 mL），這是會考與段考超過半數粗心考生的落馬點！\n• 選項 (D) 錯誤：算完 40 mL 後又重複乘了一次 2 倍得出 80 mL。",
