        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：把有機「酯化反應」誤當成無機「酸鹼中和」（況且乙醇是中性非電解質而非鹼！），且濃硫酸是催化脫水劑而非生成酯的骨架反應物。\n• 選項 (B) 錯誤：常壓下水浴溫度最高僅達水沸點 100°C，絕不可能突破 250°C；隔水加熱是為了「控溫防燃」而非衝高溫。\n• 選項 (D) 錯誤：分子態有機反應需打斷共價鍵重組，常溫不催化時極其緩慢（陳年老酒需數年才自然酯化出微香），與離子瞬間結合的酸鹼中和截然不同！",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版在酯類命名規則皆強調：「某酸 ＋ 某醇 ➔ 某酸某酯 ＋ 水」！務必看清誰提供酸、誰提供醇：乙酸＋丙醇 ➔ 乙酸丙酯；甲酸＋乙醇 ➔ 甲酸乙酯，段考選擇題最愛把「甲酸乙酯」與「乙酸甲酯」的反應物對調設陷！"
