        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱聚合物結構與性質關係（Jf-IV-4）：\n1. 鏈狀聚合物 ＝ 熱塑性聚合物：受熱易軟化熔融、冷卻固化，可重複塑形回收（代表物：聚乙烯 PE、聚丙烯 PP、聚氯乙烯 PVC、聚苯乙烯 PS、聚對苯二甲酸乙二酯 PET）。\n2. 網狀聚合物 ＝ 熱固性聚合物：分子鏈間橫向交聯鎖死，成形後受熱不軟化也不熔融（代表物：酚醛樹脂俗稱電木、尿素甲醛樹脂、美耐皿、環氧樹脂）。",
