        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢查分類：① 纖維素、② 蛋白質、③ 澱粉皆直接由動植物體內合成，屬於天然聚合物；④ 聚酯纖維由石化單體經聚合反應製得，屬於合成聚合物，故 (C) 完全正確。\n2. 檢查消化差異：雖然澱粉與纖維素皆由葡萄糖聚合，但人體缺乏分解纖維素的酵素，纖維素只能促進腸道蠕動（膳食纖維），無法被人體分解吸收產能。",
