        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱動能與功能定理（Ba-IV-7）：\n1. 速率單位換算：1 m/s ＝ 3.6 km/h，故「km/h ÷ 3.6 ＝ m/s」；動能 Ek ＝ ½ × m × v²（J）。\n2. 煞車作功與動能變化：緊急煞車滑行距離 S 期間，摩擦阻力作負功 W_f ＝ −f × S ＝ 0 − Ek_初 ⇒ S ＝ Ek_初 ÷ f ＝ (½mv²) ÷ f。當質量 m 與煞車阻力 f 固定時，煞車滑行距離 S 與初動能 Ek 成正比，即與「速率平方 v²」成正比！",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 換算時速並計算 36 km/h 時的動能：v₁ ＝ 36 km/h ＝ 36000 m ÷ 3600 s ＝ 10 m/s。代入動能公式得 Ek₁ ＝ ½ × 1500 kg × (10 m/s)² ＝ 750 × 100 ＝ 75000 J。\n2. 計算超速至 72 km/h 的動能倍數：v₂ ＝ 72 ÷ 3.6 ＝ 20 m/s，車速變為原本的 2 倍（20 ÷ 10 ＝ 2）；因 Ek ∝ v²，故新動能 Ek₂ 變為原本的 2² ＝ 4 倍（即 300000 J）！\n3. 計算緊急煞車滑行距離倍數：煞車阻力 f 不變，要消耗掉 4 倍的動能（f × S ＝ Ek），所需的煞車滑行距離 S 必然也變為原本的 4 倍，故正確答案為 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：日常直覺最大盲點！誤以為車速變 2 倍，動能與煞車距離也只變 2 倍，忽略公式中速率帶有「平方 v²」（這正是高速公路超速極易追撞的物理主因！）。\n• 選項 (C) 錯誤：忘記將 36 km/h 除以 3.6 換算成 10 m/s，直接拿 36 代入 ½ × 1500 × 36² ＝ 750 × 1296 ＝ 972000，單位不合。\n• 選項 (D) 錯誤：算動能時漏乘公式開頭的「½」（誤算成 1500 × 10² ＝ 150000 J），且誤以為煞車距離只隨速率一次方變 2 倍。",
